/**
 * Bulk-safe handler for ContactTrigger.
 *
 * Contains no direct per-record SOQL or DML. It uses at most one bulk SOQL
 * query per context and at most one bulk DML statement in total for an insert
 * or update of up to 200 contacts (before + after contexts combined).
 *
 * Behaviour is preserved from the original trigger:
 *  - Before insert/update: MailingCountry is defaulted from the account's
 *    BillingCountry when blank; LeadSource is defaulted from the account's
 *    AccountSource on insert when blank.
 *  - After insert: when several new contacts of the same account have a phone
 *    and the account has none, the first such contact (in trigger order) copies
 *    its phone onto the account.
 */
public class ContactTriggerHandler {

    /**
     * Before insert / before update: default contact fields from the account.
     * One bulk SOQL query regardless of the number of contacts.
     */
    public static void handleBefore() {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : Trigger.new) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : Trigger.new) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountMap.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (Trigger.isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * After insert: copy the first contact's phone (in trigger order) onto the
     * account when the account has none. One bulk SOQL query and one bulk DML
     * statement.
     */
    public static void handleAfter() {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : Trigger.new) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
        );

        // The map holds a single Account object per Id. Mutating it in place means
        // the first contact with a phone for a blank account wins, exactly matching
        // the original per-record behaviour (a re-query would have seen the update).
        List<Account> accountsToUpdate = new List<Account>();
        for (Contact c : Trigger.new) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account a = accountMap.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(a.Phone)) {
                a.Phone = c.Phone;
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
```

