/**
 * Bulk-safe handler for the Contact trigger.
 *
 * Design goals (per the refactor budget for an insert or update of up to 200
 * records, before + after contexts combined):
 *   - At most 1 SOQL query and 1 DML statement in total.
 *   - No per-record queries or DML.
 *
 * The accounts needed by the before context are fetched once (bulk) and cached
 * in a static map. Because static variables persist for the lifetime of the
 * transaction, the after-insert context reuses that cache without running a
 * second query. The cache is refreshed on every before-context execution so it
 * always reflects the current transaction state (important if the same
 * transaction performs multiple Contact DML operations).
 *
 * Behaviour preserved from the original trigger:
 *   - MailingCountry is defaulted from the account's BillingCountry when blank
 *     (insert and update).
 *   - LeadSource is defaulted from the account's AccountSource when blank
 *     (insert only).
 *   - On insert, when a contact has a phone and its account does not, the
 *     contact's phone is copied to the account. When several new contacts of
 *     the same account have a phone and the account has none, the first of
 *     those contacts (in trigger order) sets the account phone.
 */
public class ContactTriggerHandler {

    /**
     * Accounts read in the before context, keyed by Account Id, so the
     * after-insert context can reuse them without an additional query.
     * Always refreshed on every before-context run.
     */
    private static Map<Id, Account> accountCache = new Map<Id, Account>();

    public static void handle(List<Contact> newContacts) {
        if (newContacts == null || newContacts.isEmpty()) {
            return;
        }
        if (Trigger.isBefore) {
            handleBefore(newContacts);
        }
        if (Trigger.isAfter && Trigger.isInsert) {
            handleAfterInsert(newContacts);
        }
    }

    /**
     * Before insert/update.
     *
     * One bulk SOQL query reads every referenced account (including Phone, so
     * the after-insert context can reuse the cache). Then MailingCountry and
     * (on insert) LeadSource are defaulted from the account when blank.
     */
    private static void handleBefore(List<Contact> newContacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        Map<Id, Account> accounts = new Map<Id, Account>();
        if (!accountIds.isEmpty()) {
            accounts = new Map<Id, Account>([
                SELECT Id, BillingCountry, AccountSource, Phone
                FROM Account
                WHERE Id IN :accountIds
            ]);
        }
        // Refresh the cache so the after-insert context (same transaction) and
        // any later before context in this transaction see current data.
        accountCache = accounts;

        for (Contact c : newContacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accounts.get(c.AccountId);
            if (a == null) {
                // Defensive: in a healthy org the referenced account exists.
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (Trigger.isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * After insert.
     *
     * Copies a new contact's phone onto its account when the account has none.
     * Several contacts on the same account: the first one (in trigger order)
     * wins, matching the original behaviour. All affected accounts are updated
     * with a single DML statement.
     */
    private static void handleAfterInsert(List<Contact> newContacts) {
        if (accountCache == null || accountCache.isEmpty()) {
            return;
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Contact c : newContacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account a = accountCache.get(c.AccountId);
            if (a == null) {
                continue;
            }
            // The cached account is shared across the loop, so once an earlier
            // contact (in trigger order) has assigned the account a phone, the
            // account's Phone is no longer blank and later contacts on the same
            // account are skipped. This preserves the "first contact wins" rule
            // and guarantees each account is updated at most once.
            if (String.isBlank(a.Phone)) {
                a.Phone = c.Phone;
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
```

