/**
 * Nightly purge job for FB_Integration_Log__c records.
 *
 * Each run deletes integration logs created more than 30 days ago, except
 * logs whose Level__c is 'ERROR', which are kept until they were created
 * more than 180 days ago.
 *
 * Bulk-safe: a single SOQL query and bulk DML only (no per-record queries
 * or DML in loops).
 */
public class LogPurgeJob implements Schedulable {

    private static final Integer RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;
    private static final Integer DML_CHUNK_SIZE = 5000;

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext context) {
        DateTime now = DateTime.now();
        DateTime cutoff = now.addDays(-RETENTION_DAYS);
        DateTime errorCutoff = now.addDays(-ERROR_RETENTION_DAYS);

        // Select only the Ids of the records that must be purged:
        //  - non-ERROR logs (Level__c blank included) older than 30 days
        //  - ERROR logs older than 180 days
        List<Id> idsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (
                    (CreatedDate < :cutoff AND (Level__c = NULL OR Level__c != 'ERROR'))
                    OR
                    (CreatedDate < :errorCutoff AND Level__c = 'ERROR')
                )
        ];

        // Delete in chunks to stay within the 10,000 records-per-DML limit.
        List<Id> chunk = new List<Id>();
        for (Id id : idsToDelete) {
            chunk.add(id);
            if (chunk.size() == DML_CHUNK_SIZE) {
                delete chunk;
                chunk.clear();
            }
        }
        if (!chunk.isEmpty()) {
            delete chunk;
        }
    }

    /**
     * Schedules the purge to run every day at 02:00 (org time zone).
     *
     * @return the job Id returned by System.schedule.
     */
    public static Id scheduleNightly() {
        // Cron: seconds, minutes, hour, day-of-month, month, day-of-week
        String cronExpression = '0 0 2 * * ?';
        return System.schedule('Log purge (nightly)', cronExpression, LogPurgeJob.class);
    }
}
