/**
 * LogPurgeJob
 *
 * Nightly cleanup of FB_Integration_Log__c records:
 *  - Non-ERROR logs are purged once they are more than 30 days old.
 *  - ERROR logs are retained until they are more than 180 days old.
 *
 * The delete is bulk-safe: a single SOQL query followed by a single
 * bulk DML delete.
 */
global class LogPurgeJob implements Schedulable {

    private static final String JOB_NAME = 'Log purge (nightly)';
    private static final Integer STANDARD_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;

    public LogPurgeJob() {
    }

    global void execute(SchedulableContext ctx) {
        Datetime standardCutoff = Datetime.now().addDays(-STANDARD_RETENTION_DAYS);
        Datetime errorCutoff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);

        // Delete in one query + one bulk DML statement (no per-record work).
        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE
                // Anything older than 30 days, except ERROR logs
                (CreatedDate < :standardCutoff AND (Level__c = NULL OR LOWER(Level__c) <> 'error'))
                // or ERROR logs older than 180 days
                OR (LOWER(Level__c) = 'error' AND CreatedDate < :errorCutoff)
        ];

        if (!logsToDelete.isEmpty()) {
            Delete logsToDelete;
        }
    }

    /**
     * Schedules the nightly run for 02:00 in the org's timezone.
     *
     * @return the Cron Trigger Id returned by System.schedule
     */
    public static Id scheduleNightly() {
        // 0 0 2 ? * * ? = daily at 02:00 (org timezone)
        return System.schedule(JOB_NAME, '0 0 2 ? * * ?', new LogPurgeJob());
    }
}
```

Design notes:
- **Bulk-safe**: one SOQL in the query (no SOQL in a loop) and one bulk `Delete` — works fine for a nightly purge of a large log table.
- **Retention logic**: the SOQL `WHERE` clause encodes the two rules directly — non-ERROR rows (including blank `Level__c`) deleted when older than 30 days, and `ERROR` rows deleted only when older than 180 days. The comparison is case-insensitive (`LOWER`) so stray lowercase values don't accidentally get purged early.
- **Scheduling**: `scheduleNightly()` uses the cron `0 0 2 ? * * ?` (daily 02:00 in the org's timezone), the exact job name `Log purge (nightly)`, and returns the Cron Trigger Id from `System.schedule`.

