import { LightningElement, api } from 'lwc';
import addLabel from '@salesforce/label/c.Favorite_Add';
import removeLabel from '@salesforce/label/c.Favorite_Remove';

/**
 * Icon-style toggle button that marks a record as a favourite.
 *
 * The displayed state is derived entirely from the public `favorite`
 * property, so the parent can change it at any time (for example after a
 * server refresh) and the button always reflects that value. Clicking the
 * button flips the displayed state immediately (optimistic UI) and
 * dispatches a `favoritechange` event carrying the new value.
 */
export default class FavoriteToggle extends LightningElement {
    /**
     * Whether the record is currently a favourite. Managed by the parent.
     * @type {Boolean}
     */
    @api
    favorite;

    /**
     * Label describing the action a click will perform: the Remove label
     * when the record is a favourite, the Add label when it is not.
     * @type {String}
     */
    get actionLabel() {
        return this.favorite ? removeLabel : addLabel;
    }

    /**
     * ARIA pressed state as a string: "true" when the record is a
     * favourite, "false" otherwise.
     * @type {String}
     */
    get ariaPressed() {
        return this.favorite ? 'true' : 'false';
    }

    /**
     * Decorative star displayed inside the button. It is hidden from
     * assistive technology; the accessible name of the button comes from
     * the label (aria-label).
     * @type {String}
     */
    get icon() {
        return this.favorite ? '★' : '☆';
    }

    /**
     * Flips the displayed state immediately (optimistic UI) and dispatches
     * a `favoritechange` event whose detail is the new boolean value.
     */
    handleClick() {
        const newFavorite = !this.favorite;
        this.favorite = newFavorite;
        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                bubbles: true,
                composed: true,
                detail: { favorite: newFavorite }
            })
        );
    }
}
