import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const PERSONAL_EMAIL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleChange(event) {
        const field = event.target.dataset.field;
        this[field] = event.detail.value;
    }

    async handleRegister() {
        const emailInput = this.template.querySelector('lightning-input[data-field="email"]');

        // 1. Reject personal email domains. Done before triggering validation so
        //    this message is the one that shows for the email field.
        const domain = (this.email || '').toLowerCase().split('@').pop();
        if (PERSONAL_EMAIL_DOMAINS.includes(domain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        // 2. Trigger validation on every input so all invalid fields show
        //    their messages at once.
        const inputs = this.template.querySelectorAll('lightning-input');
        inputs.forEach((input) => input.reportValidity());

        // 3. Stop if any field is invalid.
        if ([...inputs].some((input) => !input.validity.valid)) {
            return;
        }

        // 4. Submit the registration.
        try {
            await register({ fullName: this.fullName, email: this.email, company: this.company });
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    variant: 'success'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    message: error.body.message,
                    variant: 'error'
                })
            );
        }
    }
