import register from '@salesforce/apex/RegistrationController.register';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

const NON_WORK_EMAIL_DOMAINS = new Set([
    'gmail.com',
    'yahoo.com',
    'hotmail.com',
    'outlook.com'
]);

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleChange(event) {
        const field = event.target.getAttribute('data-field');
        this[field] = event.detail.value;
    }

    handleRegister() {
        const inputs = Array.from(this.template.querySelectorAll('[data-field]'));
        const emailInput = this.template.querySelector('[data-field="email"]');

        // 1. Only work email addresses are accepted.
        const domain = (this.email || '').split('@').pop().toLowerCase();
        if (NON_WORK_EMAIL_DOMAINS.has(domain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        // 2. Show every validation message at once, even when an earlier
        //    field is already invalid. reportValidity() returns false for
        //    invalid inputs.
        let isValid = true;
        for (const input of inputs) {
            if (!input.reportValidity()) {
                isValid = false;
            }
        }

        // 3. Stop if any input is invalid.
        if (!isValid) {
            return;
        }

        register({ fullName: this.fullName, email: this.email, company: this.company })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registered',
                        message: 'You are registered for the event.',
                        variant: 'success'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registration failed',
                        message: error?.body?.message ?? 'An unexpected error occurred.',
                        variant: 'error'
                    })
                );
