import { LightningElement, api, generateId } from 'lwc';

const HANDLED_KEYS = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

export default class StatusListbox extends LightningElement {
    _uid = generateId();
    _value;
    // null = "not yet determined"; resolved lazily to the selected option
    // (or the first option when nothing is selected).
    _activeIndex = null;

    @api label;

    @api options = [];

    @api get value() {
        return this._value;
    }

    @api set value(newValue) {
        this._value = newValue;
        // When the parent changes the selection, move the active option to it.
        const selectedIndex = this.selectedIndex;
        if (selectedIndex !== -1) {
            this._activeIndex = selectedIndex;
        }
    }

    get optionCount() {
        return (this.options || []).length;
    }

    get selectedIndex() {
        return (this.options || []).findIndex(
            (option) => option.value === this._value
        );
    }

    get activeIndex() {
        const count = this.optionCount;
        if (count === 0) {
            return -1;
        }
        if (
            this._activeIndex === null ||
            this._activeIndex < 0 ||
            this._activeIndex >= count
        ) {
            // Start at the selected option, or the first option if nothing
            // is selected. Also recovers if options changed and the stored
            // index is now out of range.
            const selectedIndex = this.selectedIndex;
            return selectedIndex !== -1 ? selectedIndex : 0;
        }
        return this._activeIndex;
    }

    get listboxId() {
        return `statusListbox-${this._uid}`;
    }

    optionId(index) {
        return `${this.listboxId}-option-${index}`;
    }

    get activeDescendantId() {
        const activeIndex = this.activeIndex;
        return activeIndex === -1 ? null : this.optionId(activeIndex);
    }

    get items() {
        const options = this.options || [];
        const selectedIndex = this.selectedIndex;
        return options.map((option, index) => ({
            id: this.optionId(index),
            value: option.value,
            label: option.label,
            ariaSelected: index === selectedIndex ? 'true' : 'false'
        }));
    }

    handleKeydown(event) {
        const key = event.key;
        if (!HANDLED_KEYS.includes(key)) {
            // Every other key (notably Tab) keeps its default behaviour.
            return;
        }
        event.preventDefault();

        const count = this.optionCount;
        if (count === 0) {
            return;
        }

        const activeIndex = this.activeIndex;
        switch (key) {
            case 'ArrowDown':
                // Moving does not change the selection.
                this._activeIndex = Math.min(activeIndex + 1, count - 1);
                break;
            case 'ArrowUp':
                this._activeIndex = Math.max(activeIndex - 1, 0);
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = count - 1;
                break;
            case 'Enter':
            case ' ':
                this.selectOption(this.options[activeIndex].value);
                break;
        }
    }

    handleOptionClick(event) {
        // dataset values are strings, so look the option up by stringified
        // value and select it using its original value.
        const value = event.currentTarget.dataset.value;
        const options = this.options || [];
        const index = options.findIndex((option) => String(option.value) === value);
        if (index !== -1) {
            this.selectOption(options[index].value);
        }
    }

    selectOption(value) {
        const wasSelected = this._value === value;
        this.value = value; // also makes the selected option the active one
        if (!wasSelected) {
            this.dispatchEvent(new CustomEvent('change', { detail: { value } }));
        }
    }
}
