import { LightningElement, api, track } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api
    label;

    @track
    _value = '';

    @track
    _options = [];

    @track
    _activeIndex = 0;

    @api
    get value() {
        return this._value;
    }

    set value(value) {
        this._value = value;
        this._activeIndex = this._selectedOrFirstIndex();
    }

    @api
    get options() {
        return this._options;
    }

    set options(options) {
        this._options = options || [];
        this._activeIndex = this._selectedOrFirstIndex();
    }

    /** Stable, unique id per option: `${componentId}-option-${index}` */
    get optionIds() {
        const prefix = `${this.id || 'status-listbox'}-option-`;
        return this._options.map((option, index) => `${prefix}${index}`);
    }

    /** id of the active option, or null when there is no active option */
    get activeDescendantId() {
        const option = this._options[this._activeIndex];
        return option ? this.optionIds[this._activeIndex] : null;
    }

    connectedCallback() {
        this._activeIndex = this._selectedOrFirstIndex();
    }

    handleKeydown(event) {
        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                this._moveActive(1);
                break;
            case 'ArrowUp':
                event.preventDefault();
                this._moveActive(-1);
                break;
            case 'Home':
                event.preventDefault();
                if (this._options.length) {
                    this._activeIndex = 0;
                }
                break;
            case 'End':
                event.preventDefault();
                if (this._options.length) {
                    this._activeIndex = this._options.length - 1;
                }
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this._selectAt(this._activeIndex);
                break;
            default:
                // Every other key (notably Tab) keeps its default behaviour
                break;
        }
    }

    handleOptionClick(event) {
        const target = event.currentTarget || event.target;
        if (!target || !target.dataset || target.dataset.value === undefined) {
            return;
        }
        const value = target.dataset.value;
        const index = this._options.findIndex((option) => String(option.value) === String(value));
        if (index < 0) {
            return;
        }
        this._activeIndex = index;
        this._selectAt(index);
        const list = this.template.querySelector('ul[role="listbox"]');
        if (list) {
            list.focus();
        }
    }

    _selectedOrFirstIndex() {
        const index = this._options.findIndex((option) => option && option.value === this._value);
        return index >= 0 ? index : 0;
    }

    _moveActive(delta) {
        if (!this._options.length) {
            return;
        }
        const next = this._activeIndex + delta;
        if (next >= 0 && next < this._options.length) {
            this._activeIndex = next;
        }
    }

    _selectAt(index) {
        const option = this._options[index];
        if (!option || option.value === this._value) {
            // Nothing selectable, or the option is already selected: no event
            return;
        }
        this._value = option.value;
        this._activeIndex = index;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value }
            })
        );
    }
}
