```javascript
import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    /**
     * Accessible name of the listbox (used as aria-label).
     */
    @api label;

    _options = [];
    _value = '';
    _activeIndex = 0;

    @api
    get options() {
        return this._options;
    }
    set options(options) {
        this._options = options || [];
        this.syncActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }
    set value(value) {
        this._value = value;
        const index = this.findOptionIndex(value);
        if (index !== -1) {
            this._activeIndex = index;
        }
    }

    get displayOptions() {
        return this._options.map((option, index) => ({
            value: option.value,
            label: option.label,
            id: `status-listbox-option-${index}`,
            selected: option.value === this._value
        }));
    }

    get activeOptionId() {
        const active = this.displayOptions[this._activeIndex];
        return active ? active.id : '';
    }

    findOptionIndex(value) {
        return this._options.findIndex((option) => option.value === value);
    }

    syncActiveIndex() {
        this._activeIndex = this.clampIndex(this.findOptionIndex(this._value));
    }

    clampIndex(index) {
        if (this._options.length === 0) {
            return 0;
        }
        return Math.max(0, Math.min(index, this._options.length - 1));
    }

    moveActive(delta) {
        this._activeIndex = this.clampIndex(this._activeIndex + delta);
    }

    handleKeydown(event) {
        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                this.moveActive(1);
                break;
            case 'ArrowUp':
                event.preventDefault();
                this.moveActive(-1);
                break;
            case 'Home':
                event.preventDefault();
                this._activeIndex = this.clampIndex(0);
                break;
            case 'End':
                event.preventDefault();
                this._activeIndex = this.clampIndex(this._options.length - 1);
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this.selectActiveOption();
                break;
            default:
                // Every other key (notably Tab) keeps its default behaviour.
                break;
        }
    }

    selectActiveOption() {
        const option = this._options[this._activeIndex];
        if (option) {
            this.selectOption(option.value);
        }
    }

    handleOptionClick(event) {
        const value = event.currentTarget.dataset.value;
        const index = this.findOptionIndex(value);
        if (index !== -1) {
            this._activeIndex = index;
            this.selectOption(value);
        }
    }

    selectOption(value) {
        if (value === this._value) {
            return;
        }
        this._value = value;
        this.dispatchEvent(new CustomEvent('change', { detail: { value } }));
    }
}
